const u=k=>UX[app.lang]?.[k]||UX.ko[k]||k;
const GUIDE={
status:['git status'],stage:['git status','git add README.md'],commit:['git status','git add README.md','git commit -m "docs: update guide"'],diff:['git diff'],log:['git log --oneline'],show:['git show HEAD'],unstage:['git add README.md','git restore --staged README.md'],newbranch:['git switch -c feature/login'],featurecommit:['git switch -c feature/login',{edit:'app.js',value:'export const version = 2;'},'git add app.js','git commit -m "feat: login"'],merge:['git branch','git merge feature/login'],resolve:[{edit:'app.js',value:'export const theme = "dark";' },'git add app.js','git commit -m "merge: resolve conflict"'],graph:['git log --graph --oneline --all'],branchlist:['git branch'],remote:['git remote add origin https://example.invalid/team/demo.git','git remote -v'],push:['git push -u origin main'],fetch:['git fetch origin'],pull:['git pull origin main'],audit:['git status','git log --oneline'],selective:['git status','git add app.js'],restore:['git status','git restore README.md'],revert:['git log --oneline','git revert HEAD'],reflog:['git reflog'],softreset:['git log --oneline','git reset --soft HEAD~1'],stash:['git status','git stash'],stashpop:['git stash list','git stash pop'],tag:['git tag v1.0.0'],cherry:['git cherry-pick fix'],rebase:['git rebase main'],ignore:[{edit:'.gitignore',append:'.env'},'git status'],capstone:['git switch -c feature/final',{edit:'app.js',value:'export const version = 3;'},'git add app.js','git commit -m "feat: final"','git switch main','git merge feature/final','git tag v2.0.0']};
function steps(lab){if(lab.id==='L08'&&app.engine?.s.branch==='feature/login')return [{edit:'app.js',value:'export const version = 2;'},'git add app.js','git commit -m "feat: login"'];if(lab.id==='L04'||lab.id==='L30')return [{edit:'app.js',append:'greet'},'git status','git diff'];if(lab.id==='L02')return [{edit:'README.md',append:'Getting started'},'git status','git diff','git add README.md'];if(lab.id==='L03')return ['git status','git diff --staged','git commit -m "docs: update guide"'];let all=[...(GUIDE[lab.goal]||['git status'])];if(lab.id==='L29')all=['git status','git add app.js'];if(lab.id==='L30')all=['git diff'];if(lab.id==='L32')all=['git log --oneline','git revert HEAD'];if(lab.id==='L33')all=['git reflog'];if(lab.id==='L34')all=['git tag v1.0.0'];if(lab.id==='L35')all=['git status','git log --oneline'];return all;}
function guidedState(lab){
 const entries=(app.engine.s.terminal||[]).filter((x,i,a)=>x.type==='command'&&a[i+1]?.type!=='error').map(x=>x.text.slice(2));
 let cursor=0;
 return steps(lab).map(step=>{
  const edit=typeof step==='object';let done=false;
  if(edit){
   const value=app.engine.s.working[step.edit]||'';
   if(lab.id==='L02'&&step.edit==='README.md')done=value.trim().length>0&&value!==app.engine.snap()['README.md'];
   else done=step.append?value.includes(step.append):value.trim()===step.value.trim();
  }else{const i=entries.findIndex((cmd,j)=>j>=cursor&&cmd.trim()===step);done=i!==-1;if(done)cursor=i+1;}
  return {step,edit,done};
 });
}
function stepsView(lab){
 const progress=guidedState(lab);const doneCount=progress.filter(x=>x.done).length;
 const currentStepIndex=progress.findIndex(x=>!x.done);
 const next=progress.find(x=>!x.done);
 const nextLabel=next?(next.edit?`${next.step.edit} · ${u('manual')}`:next.step):f('guideFinished');
 return `<div class="guide-title"><strong>🧭 ${safe(u('guide'))}</strong><span>${lab.id} · ${doneCount}/${progress.length}</span></div>
 <p class="guide-desc">${safe(u('guideDesc'))}</p>
 <div class="guide-progress" role="status" aria-live="polite"><strong>${safe(f('guideProgress'))}: ${doneCount}/${progress.length}</strong><span>${safe(f('guideNext'))}: ${safe(nextLabel)}</span>${lab.id==='L02'?`<small>${safe(f('lessonFinish'))}</small>`:''}</div>
 <ol class="guided-steps">${progress.map(({step,edit,done},index)=>{
  const txt=edit?`${step.edit} · ${u('manual')}`:step;
  const description=done&&edit?f('editDone'):edit&&lab.id==='L02'?f('readmeStep'):edit?u('manualDesc'):u('commandDesc');
  return `<li class="guided-step ${done?'step-complete':index===currentStepIndex?'step-current':''}" data-guide-index="${index}" ${index===currentStepIndex?'aria-current="step"':''}><span class="step-count">${done?'✓':index+1}</span><div class="step-main"><strong>${safe(txt)}</strong><small>${safe(description)}</small>${edit?`<button type="button" class="btn secondary sm" data-edit-file="${safe(step.edit)}">✎ ${safe(u('manual'))} →</button>`:`<button type="button" class="btn secondary sm" data-fill-command="${safe(step)}">⌨ ${safe(u('fill'))} →</button>${index===currentStepIndex?(window.GitCommandGuide?.render(step,app.lang,{allowPlain:true})||''): ''}`}</div></li>`;
 }).join('')}</ol><p class="guide-foot">💡 ${safe(u('tip'))}</p>`;
}

