SUP.ko.bookMore='전자책으로 자세히 배우기';SUP.en.bookMore='Read full explanation in PDF';SUP.ja.bookMore='PDF の詳しい解説を見る';SUP.zh.bookMore='在 PDF 中查看详细说明';
SUP.ko.addendum='v1.2 새 실습 해설 · 70~75쪽';SUP.en.addendum='v1.2 New practice guide · pp. 70–75';SUP.ja.addendum='v1.2 新しい演習ガイド · 70～75ページ';SUP.zh.addendum='v1.2 新实训指南 · 第70～75页';
const z=k=>(SUP[app.lang]||SUP.ko)[k]||SUP.ko[k]||k;
function terminalText(text){return String(text).split('\n').map(line=>{
 let cls='term-normal';if(line.startsWith('diff --git ')||line.startsWith('@@'))cls='term-diff-head';
 else if(line.startsWith('--- '))cls='term-diff-from';else if(line.startsWith('+++ '))cls='term-diff-to';
 else if(line.startsWith('-'))cls='term-diff-remove';else if(line.startsWith('+'))cls='term-diff-add';
 return `<div class="terminal-code-line ${cls}">${line===' '? '&nbsp;':safe(line)||'&nbsp;'}</div>`;
 }).join('');}
function outputBookTopic(e){const arr=e?.s?.terminal||[];const at=arr.map(x=>x.type).lastIndexOf('command');if(at<0)return 'status';const output=arr[at+1]||{};if(output.type==='error')return 'error';const cmd=arr[at].text.replace(/^\$\s*/,'').trim().split(/\s+/);const sub=cmd[1]||'status';return Object.prototype.hasOwnProperty.call(window.BOOK_OUTPUT||{},sub)?sub:'general';}
function outputBookButton(e){const topic=outputBookTopic(e),page=(window.BOOK_OUTPUT||{})[topic]||95;return `<button class="btn subtle sm" data-book-output="${safe(topic)}">▧ ${safe(z('bookMore'))} · PDF ${page}${safe(t('page'))}</button>`;}
function explainOutput(e){const term=e.s.terminal||[],i=term.map(x=>x.type).lastIndexOf('command');
 const cmd=i<0?'':term[i].text.replace(/^\$\s*/,'');const output=i<0?'':term[i+1]?.text||'';
 let keys=[];
 if(cmd.startsWith('git status')){keys=['branch'];if(output.includes('Changes not staged'))keys.push('notStaged');if(output.includes('Changes to be committed'))keys.push('staged');if(output.includes('modified:'))keys.push('modified');if(output.includes('Untracked files'))keys.push('untracked');if(output.includes('working tree clean'))keys.push('clean');}
 else if(cmd.startsWith('git diff')){keys=[cmd.includes('--staged')||cmd.includes('--cached')?'diffStagedHead':'diffHead'];if(output.includes('(no diff)'))keys.push('noDiff');else keys.push('diffFile','old','fresh','hunk',...(output.split('\n').some(x=>x.startsWith('-')&&!x.startsWith('---'))?['removed']:[]),...(output.split('\n').some(x=>x.startsWith('+')&&!x.startsWith('+++'))?['added']:[]),'same');}
 else if(cmd){
 const map={add:'stageCmd',commit:'commitCmd',log:'logCmd',merge:'mergeCmd',restore:'restoreCmd',show:'showCmd',branch:'branchCmd',switch:'switchCmd',remote:'remoteCmd',push:'pushCmd',fetch:'fetchCmd',pull:'pullCmd',revert:'revertCmd',reset:'resetCmd',reflog:'reflogCmd',stash:'stashCmd',tag:'tagCmd','cherry-pick':'cherryCmd',rebase:'rebaseCmd'};
 keys=[map[cmd.split(' ')[1]]||'generic'];
 }
 if(output.startsWith('error:'))keys.unshift('errorCmd');
 if(!keys.length)return `<div class="explain-empty">${safe(z('emptyOutput'))}</div>`;
 return `<div class="explain-items">${keys.map((key,index)=>{
 let desc=z(key);
 if(key==='branch'){const found=output.match(/^On branch ([^\r\n]+)$/m);const branch=found?found[1].trim():(e.s.branch||'');desc=desc.replaceAll('{branch}',branch); }
 if(key==='modified'){const found=output.match(/modified:\s*(\S+)/);if(found)desc=desc.replaceAll('app.js',found[1]);}
 return `<div class="explain-row"><span class="explain-number">${index+1}</span><p>${safe(desc)}</p></div>`;
 }).join('')}</div>`;
}
function flowView(e,file){const hist=e.s.history||[],q=e.status(),saved=Object.keys(q.modified).length>0||q.untracked.length>0||q.staged.length>0;
 const parts=[[z('flow1'),saved],[z('flow2'),hist.some(x=>x.startsWith('git diff'))],[z('flow3'),q.staged.length>0||hist.some(x=>x.startsWith('git add'))],[z('flow4'),hist.some(x=>x.startsWith('git diff --staged'))],[z('flow5'),hist.some(x=>x.startsWith('git commit'))]];
 return `<div class="flow-strip"><div class="flow-heading">${safe(z('quick'))}<small>${safe(z('stateFlow'))}</small></div><div class="flow-checks">${parts.map(([label,yes],i)=>`<span class="flow-step ${yes?'okay':''}">${yes?'✓':i+1} ${safe(label)}</span>`).join('')}</div><div class="flow-actions"><button class="btn subtle sm" data-fill-command="git diff">git diff</button><button class="btn subtle sm" data-fill-command="git add ${safe(file||'app.js')}">git add ${safe(file||'app.js')}</button><button class="btn subtle sm" data-fill-command="git diff --staged">git diff --staged</button><button class="btn subtle sm" data-fill-command='git commit -m "feat: update project"'>git commit</button></div></div>`;
}

