const app={sidebarCompact:true,sidebarExplicit:false,lang:langs.includes(requestedLanguage)?requestedLanguage:(langs.includes(old.lang)?old.lang:(langs.includes(legacy.lang)?legacy.lang:'ko')),done:old.done||{},sessions:old.sessions||{},starts:old.starts||{},page:'dashboard',active:'L01',engine:null,file:'README.md',hint:false,notice:'',showHelp:false,graphAll:false,preview:false,commandError:false,explanationRead:{},bookPages:window.BOOK_PAGES||{},search:'',terminalBuffer:[],terminalPos:0};
