function moduleDone(n){return lessons.filter(x=>x.chapter===n&&app.done[x.id]).length}
function firstUnfinished(){return lessons.find(x=>!app.done[x.id])||lessons[lessons.length-1]}
function heroVisual(){return `<div class="terminal-display"><div class="window-bar"><span class="dot"></span><span class="dot"></span><span class="dot"></span><span class="window-title">gitmaster / lesson 01</span></div><div class="terminal-preview"><span class="term-cyan">➜</span> <span class="term-green">git status</span>\n<span class="term-muted">On branch main</span>\n<span class="term-muted">Changes to be committed:</span>\n  <span class="term-green">modified: README.md</span>\n\n<span class="term-cyan">➜</span> <span class="term-purple">git commit -m "learn by doing"</span>\n<span class="term-green">✓ Your first commit is ready.</span></div></div>`}
function overview(){const next=firstUnfinished();return `<section class="welcome-guide"><div><span class="eyebrow">START HERE · 01 / 02 / 03</span><h2>${safe(u('welcome'))}</h2><div class="welcome-flow">${[['first','firstDesc'],['second','secondDesc'],['third','thirdDesc']].map(a=>`<div class="welcome-step"><strong>${safe(u(a[0]))}</strong><span>${safe(u(a[1]))}</span></div>`).join('')}</div></div><button class="btn primary" data-go="gitIntro">🎬 ${safe(t('gitIntro'))} →</button></section><section class="hero"><div class="hero-inner"><div class="eyebrow">✦ ${t('heroLabel')}</div><h1>${safe(t('heroTop'))}<br><span class="gradient-text">${safe(t('heroBottom'))}</span></h1><p class="lead">${safe(t('heroDesc'))}</p><div class="button-row"><button class="btn secondary" data-go="gitIntro">▶ ${safe(t('gitIntro'))}</button><button class="btn primary" data-go="lab/${next.id}">↗ ${safe(t(stats()?'continue':'start'))}</button><button class="btn secondary" data-go="setup">⚙ ${safe(t('setup'))}</button><button class="btn secondary" data-go="courses">${safe(t('browse'))} →</button><button class="btn subtle" data-go="history">⌁ ${safe(t('history'))}</button></div></div><div class="hero-visual">${heroVisual()}</div><span class="hero-glow"></span></section><div class="stat-grid">${[[String(stats()).padStart(2,'0')+' / 36',t('completed'),'✓'],['12',t('chapters'),'◈'],['36',t('labs'),'⌘'],[percent()+'%',t('progress'),'↗']].map(x=>`<div class="stat-card"><span class="spark">${x[2]}</span><div class="metric">${x[0]}</div><div class="metric-label">${safe(x[1])}</div></div>`).join('')}</div>${teamCourseCTA()}<section class="exam-cta"><div><span class="eyebrow">FINAL ASSESSMENT</span><strong>${safe(t('assessment'))}</strong><p>${safe({ko:'36개 실습을 마친 후, 하나의 FocusBoard 프로젝트에서 9개 실무 과제를 종합 점검합니다.',en:'Nine real-world Git assignments in one continuous FocusBoard project.',ja:'9つの実務課題でGitを総合評価。',zh:'一个FocusBoard项目中完成9个真实Git任务。'}[app.lang])}</p></div><button class="btn primary" data-go="assessment">${safe(t('assessment'))} →</button></section><div class="section-top"><div><h2>${safe(t('courseTitle'))}</h2><p>${safe(t('courseDesc'))}</p></div><a href="#courses" class="text-link">${safe(t('seeAll'))} ↗</a></div><div class="course-grid">${chapters.slice(0,6).map(courseCard).join('')}</div>`}
function courseCard(ch){const n=moduleDone(ch.id),first=lessons.find(x=>x.chapter===ch.id),summary=app.lang==='ko'?ch.summary:`${3} ${t('lessons')} · Git`;return `<article class="course-card"><div class="module-number"><span>CHAPTER ${String(ch.id).padStart(2,'0')}</span><span class="chip ${n===3?'done':''}">${n===3?'✓ '+t('done'):`${n}/3`}</span></div><h3>${safe(L(ch.title))}</h3><p>${safe(summary)}</p><div class="progress-track"><span style="width:${n/3*100}%"></span></div><div class="meta-row"><span>${n}/3 ${t('lessons')}</span><a href="#lab/${first.id}" class="text-link">${t('open')} ↗</a></div></article>`}
function teamCourseCTA(){const lang=app.lang;const desc={ko:'6장 원격 저장소 학습 후 진행: 4명의 개발자가 PR 작성 → 코드 리뷰 → 수정 요청 → 재승인 → 보호된 main 병합을 직접 수행합니다.',en:'After Chapter 6: Four developers create, review, revise, approve and merge two protected-branch pull requests.',ja:'第6章の後に、4人の開発者がPRの作成・レビュー・修正・承認・マージを体験します。',zh:'第6章后，四位开发者通过两个PR练习创建、审查、修改、批准与合并。'}[lang];return `<section class="team-course-cta"><div><span class="eyebrow">AFTER CHAPTER 06 · BEFORE CHAPTER 07</span><h2>🤝 ${safe(t('collaboration'))} <span class="team-course-count">10 MISSIONS</span></h2><p>${safe(desc)}</p></div><button class="btn primary" data-go="collaboration">${safe(t('open'))} →</button></section>`}
function courseList(){return `<div class="page-head"><div><div class="eyebrow">CURRICULUM / 12 CHAPTERS</div><h1>${safe(t('courses'))}</h1><p>${safe(t('courseDesc'))}</p></div><button class="btn secondary sm" data-go="gitIntro">▶ ${safe(t('gitIntro'))}</button><button class="btn secondary sm" data-export="1">↓ ${safe(t('saveProgress'))}</button></div>${chapters.map(ch=>`<section class="module-section"><div class="module-head"><span class="module-index">${String(ch.id).padStart(2,'0')}</span><h2 style="margin:0">${safe(L(ch.title))}</h2><span class="chip ${moduleDone(ch.id)===3?'done':''}">${moduleDone(ch.id)}/3</span></div><div class="module-row">${lessons.filter(x=>x.chapter===ch.id).map(x=>`<button class="lesson-tile" data-go="lab/${x.id}"><span class="lab-id">${x.id} / 36</span>${app.done[x.id]?'<span class="check-icon">✓</span>':''}<h3>${safe(L(x.title))}</h3><p>${safe(L(x.description))}</p></button>`).join('')}</div></section>${ch.id===6?teamCourseCTA():''}`).join('')}<section class="exam-cta"><div><span class="eyebrow">FINAL PROJECT</span><strong>${safe(t('assessment'))}</strong><p>FocusBoard · 9 tasks · 100 points</p></div><button class="btn primary" data-go="assessment">${safe(t('assessment'))} →</button></section>`}
function getEngine(lab){
 if(app.active!==lab.id||!app.engine){
  app.active=lab.id;const saved=app.sessions[lab.id]||null;
  if(saved){app.engine=new GitLabEngine(lab.scenario,saved);}
  else{
   const n=lessons.indexOf(lab),prev=lessons.slice(0,n).reverse().find(x=>app.done[x.id]&&app.sessions[x.id]);
   app.engine=(prev&&app.done[prev.id]&&app.sessions[prev.id])
    ?GitLabEngine.continueFrom(lab.scenario,app.sessions[prev.id],prev.id,lab.id)
    :new GitLabEngine(lab.scenario);
   if(['L04','L30'].includes(lab.id)){app.engine.s.meta.requiresEdit=true;}
   app.starts[lab.id]=JSON.parse(JSON.stringify(app.engine.s));
   app.sessions[lab.id]=app.engine.s;persist();
  }
  if(!app.starts[lab.id])app.starts[lab.id]=JSON.parse(JSON.stringify(app.engine.s));
  app.file=lab.goal==='ignore'?'.gitignore':(['resolve','diff','selective','featurecommit','capstone'].includes(lab.goal)?'app.js':'README.md');
  app.hint=false;app.notice='';app.commandError=false;app.graphAll=false;app.preview=false;
 }
 return app.engine;
}

function graphView(s,commits){
 const firstParentMain=new Set();let cursor=s.branches.main;
 while(cursor&&!firstParentMain.has(cursor)){firstParentMain.add(cursor);cursor=s.commits[cursor]?.parents[0]||null;}
 const ids=new Map(commits.map((c,i)=>[c.id,i]));
 const side=new Map();for(const [name,id] of Object.entries(s.branches)){if(name==='main')continue;let at=id;while(at&&!firstParentMain.has(at)&&!side.has(at)){side.set(at,1+side.size%2);at=s.commits[at]?.parents[0];}}
 const lane=id=>firstParentMain.has(id)?0:(side.get(id)||1);
 const xx=id=>14+lane(id)*25,yy=id=>20+(ids.get(id)||0)*48;
 const paths=[];for(const c of commits){for(const parent of c.parents){if(!ids.has(parent))continue;const x1=xx(c.id),y1=yy(c.id),x2=xx(parent),y2=yy(parent),mid=(y1+y2)/2;paths.push(`<path d="${x1===x2?`M ${x1} ${y1} L ${x2} ${y2}`:`M ${x1} ${y1} C ${x1} ${mid}, ${x2} ${mid}, ${x2} ${y2}`}" fill="none" stroke="${x1===x2?'#6484c3':'#58bdb9'}" stroke-width="2" opacity=".85"/>`);}}
 const refs={};for(const [name,id] of Object.entries(s.branches))(refs[id]||=[]).push(name);
 for(const [name,id] of Object.entries(s.tags||{}))(refs[id]||=[]).push('🏷 '+name);
 const markers={};for(const m of s.milestones||[])(markers[m.head]||=[]).push(m.lab);
 const circles=commits.map(c=>`<circle cx="${xx(c.id)}" cy="${yy(c.id)}" r="5.7" fill="#10223a" stroke="${c.id===s.branches[s.branch]?'#7ce8ce':'#8cabff'}" stroke-width="3"/>`).join('');
 const rows=commits.map(c=>`<div class="graph-copy-row" title="${safe(c.message)}"><span class="graph-commit"><b>${safe(c.id)}</b> ${safe(c.message)}</span>${refs[c.id]?`<span class="graph-refs">${safe(refs[c.id].join(' · '))}${c.id===s.branches[s.branch]?' · HEAD':''}</span>`:''}${markers[c.id]?`<span class="graph-milestone">✓ ${safe(markers[c.id].join(', '))}</span>`:''}</div>`).join('');
 return `<div class="graph-vis" style="height:${commits.length*48}px"><svg viewBox="0 0 90 ${commits.length*48}" aria-label="Git commit parent graph" role="img">${paths.join('')}${circles}</svg><div class="graph-copy">${rows}</div></div>`;
}

function lastOutputKey(s){
 const term=s?.terminal||[];
 const last=term.map(item=>item.type).lastIndexOf('command');
 return last<0?'':`${s.history?.length||0}:${last}:${term.length}`;
}
