 <div class="lab-help-top"><div>❔ ${safe(u('journey'))}<span class="history-banner">⌁ ${safe(z('journey'))}: ${connected}</span></div><button class="btn secondary sm" id="toggle-onboard">${safe(app.showHelp?u('closeStart'):u('showStart'))} ▾</button></div>
