let lastRenderedRoute="";
// Keep independently scrollable workspace panes in place when the app redraws.
// Never use scrollIntoView() for automatic guidance: it may scroll the entire
// page and pull keyboard focus away from the Git terminal.
function revealInPane(pane,target){
 if(!pane||!target||pane.scrollHeight<=pane.clientHeight+1)return;
 const outer=pane.getBoundingClientRect(),inner=target.getBoundingClientRect();
 const margin=14;
 if(inner.top<outer.top+margin){
  pane.scrollTop+=inner.top-outer.top-margin;
 }else if(inner.bottom>outer.bottom-margin){
  pane.scrollTop+=inner.bottom-outer.bottom+margin;
 }
}
// Keep the most recent command and its output visible after a full DOM redraw.
// The first assignment handles the synchronous layout; two animation frames
// cover later flex/grid sizing without scrolling the whole document.
function scrollTerminalToLatest(id){
 const container=document.getElementById(id);
 if(!container)return;
 const snap=()=>{
  if(document.getElementById(id)!==container)return;
  container.scrollTop=Math.max(0,container.scrollHeight-container.clientHeight);
 };
 snap();
 if(typeof window.requestAnimationFrame==='function')window.requestAnimationFrame(()=>{snap();window.requestAnimationFrame(snap);});
}
